package ai.novita.sandbox.core; public class VolumeOptions { private long quotaGiB; private Long quotaInodes; private boolean quotaSet; public long getQuotaGiB(){return quotaGiB;} public VolumeOptions setQuotaGiB(long v){if(v<0)throw new IllegalArgumentException("quotaGiB must be non-negative");quotaGiB=v;quotaSet=true;return this;} public Long getQuotaInodes(){return quotaInodes;} public VolumeOptions setQuotaInodes(Long v){if(v!=null&&v<0)throw new IllegalArgumentException("quotaInodes must be non-negative");quotaInodes=v;if(v!=null)quotaSet=true;return this;} /** True when a quota field was explicitly set, mirroring JS {@code !== undefined}. */ public boolean hasQuota(){return quotaSet;} }
